// CPU-only original authentication/preparation. PRIVATE generated bytes stay
// outside Git;no device/installed cache/Work capability or model mutation.
#if defined(_KERNEL_MODE) || defined(PIONEER_Q38_WORK_INFERENCE) || defined(PIONEER_Q38_CPU_VALIDATION) || defined(__FAST_MATH__)
#error Diagnostic86 exporter is not a kernel/Work/CPU-validation capability
#endif
#include "PioneerQwen38Gguf.h"
#include "PioneerModelWeightCache.h"
#include "PioneerQ38Q4FpuBlockData.h"
#include "PioneerBlackholeBf16Arithmetic.h"
#include <array>
#include <cstdio>
#include <cstring>
#include <dirent.h>
#include <fcntl.h>
#include <memory>
#include <stdexcept>
#include <sys/stat.h>
#include <unistd.h>
#include <vector>
namespace {
using Cache=PioneerModelWeightCache;
void Require(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
uint32_t Word(const uint8_t* p){return uint32_t(p[0])|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16)|(uint32_t(p[3])<<24);}
FILE* NewFile(const std::string& path) {
	int fd=open(path.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_CLOEXEC|O_NOFOLLOW,0600);
	Require(fd>=0,"Private output exists or cannot be created.");
	FILE* f=fdopen(fd,"wb");if(!f){close(fd);throw std::runtime_error("Private stream failed.");}return f;
}
void Finish(FILE* f) {
	bool okay=!ferror(f) && !fflush(f) && !fsync(fileno(f));bool closed=!fclose(f);
	Require(okay && closed,"Private output incomplete;DO NOT COMPILE.");
}
void Bytes(const std::string& path,const void* p,size_t n) {
	FILE* f=NewFile(path);Require(fwrite(p,1,n,f)==n,"Private output short write;DO NOT COMPILE.");Finish(f);
}
void Array(FILE* f,const char* name,const uint8_t* bytes,unsigned n) {
	Require(!(n&3),"Unaligned generated array.");fprintf(f," static const uint32_t %s[%u]={\n",name,n/4);
	for(unsigned i=0;i<n;i+=4)fprintf(f,"%s0x%08x%s",i%32?"":"  ",Word(bytes+i),i+4==n?"\n":i%32==28?",\n":",");
	fputs(" };\n",f);
}

struct Sample {
 unsigned tensor=0,width=0,first=0;
 std::vector<uint8_t> original,prepared,input;
 std::array<uint8_t,128> expected{};
};
unsigned Width(unsigned s){return s<6?5120:17408;}
unsigned Tensor(unsigned s){return s<3?7:s<6?8:6;}
unsigned First(unsigned s){return s%3==0?0:s%3==1?(s<6?8704:2560):(s<6?17376:5088);}
int Run(int argc,char** argv) {
 if(argc!=3){fputs("Use ORIGINAL_GGUF NEW_EMPTY_PRIVATE_DIRECTORY;CPU_ONLY.\n",stderr);return 2;}
 struct stat info{};Require(!lstat(argv[2],&info) && S_ISDIR(info.st_mode) && info.st_uid==geteuid()
  && (info.st_mode&07777)==0700,"Output must be owned private directory,not a symlink.");
 DIR* directory=opendir(argv[2]);Require(directory,"Cannot inspect private output.");
 bool empty=true;while(auto* p=readdir(directory))if(strcmp(p->d_name,".") && strcmp(p->d_name,".."))empty=false;
 Require(!closedir(directory) && empty,"Private output is not empty;never overwrite.");
 std::unique_ptr<FILE,decltype(&fclose)> f(fopen(argv[1],"rb"),fclose);Require(bool(f),"Original model unavailable.");
 PioneerQwen38Gguf model;Require(model.Open(f.get()),"Original851-tensor model layout refused.");
 uint64_t epoch=model.Epoch();Cache::Digest sha{};std::string error;
 puts("AUTHENTICATING_COMPLETE_SAME_OPEN_ORIGINAL;CPU_ONLY_NO_DEVICE");fflush(stdout);
 Require(Cache::HashFile(fileno(f.get()),PioneerQwen38Gguf::FullBytes,sha,error)
  && Cache::Hex(sha)=="c600de0300ae8a0eb3a6c0b8b5561b8b96f16bd2c863c2a66c42de29d391a747"
  && model.Stable() && model.Epoch()==epoch,"Full original SHA/epoch refused.");
 std::array<Sample,9> samples;
 for(unsigned s=0;s<9;s++) {
  auto& p=samples[s];p.tensor=Tensor(s);p.width=Width(s);p.first=First(s);unsigned blocks=p.width/256;
  const auto& t=model.Tensors()[p.tensor];const char* name=s<3?"blk.0.ffn_gate.weight":s<6?"blk.0.ffn_up.weight":"blk.0.ffn_down.weight";
  Require(t.name==name && t.type==12 && t.inputs==p.width && t.outputs==(s<6?17408:5120),"Pinned original Q4 matrix refused.");
  p.original.resize(blocks*4608);p.prepared.resize(blocks*6144);p.input.resize(blocks*512);
  uint32_t total[32]={};
  for(unsigned block=0;block<blocks;block++) {
   auto* raw=p.original.data()+block*4608;
   for(unsigned row=0;row<32;row++)Require(model.ReadPacked(p.tensor,(uint64_t(p.first+row)*blocks+block)*144,144,raw+row*144,144),"Original full-K band read refused.");
   Require(PioneerQ38Q4FpuBlockData::Prepare(raw,4608,p.prepared.data()+block*6144,6144),"Q4 preparation refused.");
   uint16_t input[256];
   for(unsigned c=0;c<256;c++){input[c]=uint16_t(0x3e80+(c*19+block*11)%384+((c&3)==2?0x8000:0));p.input[block*512+c*2]=uint8_t(input[c]);p.input[block*512+c*2+1]=uint8_t(input[c]>>8);}
   // Separate diagnostic oracle;NEVER compiled into the kernel/Work worker.
   for(unsigned row=0;row<32;row++) {
    float weights[256];Require(PioneerDecodeQ4K(raw+row*144,weights),"Original decode refused.");
    for(unsigned first=0;first<256;first+=16) {
     uint16_t a[16],b[16];for(unsigned k=0;k<16;k++) {
      uint32_t bits;memcpy(&bits,&weights[first+k],4);
      Require((bits&0x7f800000)!=0x7f800000 && (!(bits&0x7fffffff) || (bits&0x7f800000)),"Non-finite/denormal reference refused.");
      uint32_t high=bits>>16,low=bits&65535;high+=low>32768 || (low==32768 && (high&1));a[k]=uint16_t(high);b[k]=input[first+k];
     }
     for(unsigned phase=0;phase<4;phase++)Require(PioneerBlackholeBf16Arithmetic::Instruction(a,b,phase,total[row],total[row]),"Rounded reference refused.");
    }
   }
  }
  for(unsigned r=0;r<32;r++)for(unsigned b=0;b<4;b++)p.expected[r*4+b]=uint8_t(total[r]>>(8*b));
  Require(model.Stable() && model.Epoch()==epoch,"Original epoch changed during preparation.");
 }
 const std::string path=argv[2];
 FILE* data=NewFile(path+"/PioneerNativeQ4FpuStreamData.h");
 fputs("/* PRIVATE GENERATED learned weights;DO NOT COMMIT OR REDISTRIBUTE. */\n#ifndef PIONEER_NATIVE_Q4_FPU_STREAM_DATA_H\n#define PIONEER_NATIVE_Q4_FPU_STREAM_DATA_H\n#include <stdint.h>\nstruct PioneerNativeQ4FpuStreamData {\n static constexpr unsigned Version=1,Rows=32,Samples=9,Role=86;\n static unsigned Width(unsigned s){return s<6?5120:s<9?17408:0;}\n static unsigned Words(unsigned s){return s<9?(Width(s)/256)*1664:0;}\n static uint32_t Word(unsigned sample,unsigned index){if(sample>=9 || index>=Words(sample))return 0;\n",data);
 for(unsigned s=0;s<9;s++){char name[16];snprintf(name,sizeof(name),"p%u",s);Array(data,name,samples[s].prepared.data(),unsigned(samples[s].prepared.size()));snprintf(name,sizeof(name),"i%u",s);Array(data,name,samples[s].input.data(),unsigned(samples[s].input.size()));}
 fputs(" unsigned weight=Width(sample)/256*1536;\n if(index<weight){switch(sample){\n",data);
 for(unsigned s=0;s<9;s++)fprintf(data," case %u:return p%u[index];\n",s,s);
 fputs(" }}else{index-=weight;switch(sample){\n",data);for(unsigned s=0;s<9;s++)fprintf(data," case %u:return i%u[index];\n",s,s);
 fputs(" }}return 0;}\n};\n#endif\n",data);Finish(data);
 FILE* meta=NewFile(path+"/PioneerNativeQ4FpuStreamMetadata.h");
 fputs("/* PRIVATE GENERATED diagnostic predictions,NOT Work/model quality. */\n#ifndef PIONEER_NATIVE_Q4_FPU_STREAM_METADATA_H\n#define PIONEER_NATIVE_Q4_FPU_STREAM_METADATA_H\n#include <stdint.h>\nstruct PioneerNativeQ4FpuStreamMetadata {\n static constexpr unsigned Rows=32,Samples=9;\n static unsigned Tensor(unsigned s){return s<3?7:s<6?8:s<9?6:~0U;}\n static unsigned Width(unsigned s){return s<6?5120:s<9?17408:0;}\n static unsigned First(unsigned s){return s>=9?~0U:s%3==0?0:s%3==1?(s<6?8704:2560):(s<6?17376:5088);}\n static const uint32_t* Golden(unsigned s){\n",meta);
 for(unsigned s=0;s<9;s++){char name[16];snprintf(name,sizeof(name),"g%u",s);Array(meta,name,samples[s].expected.data(),128);}
 fputs(" switch(s){\n",meta);for(unsigned s=0;s<9;s++)fprintf(meta," case %u:return g%u;\n",s,s);
 fputs(" }return nullptr;}\n};\n#endif\n",meta);Finish(meta);
 for(unsigned s=0;s<9;s++) {
  const auto& p=samples[s];std::string prefix=path+"/sample"+std::to_string(s);
  Bytes(prefix+".original.bin",p.original.data(),p.original.size());Bytes(prefix+".prepared.bin",p.prepared.data(),p.prepared.size());
  Bytes(prefix+".input.bin",p.input.data(),p.input.size());Bytes(prefix+".expected.bin",p.expected.data(),128);
  printf("PRIVATE_Q4_STREAM_SAMPLE%u tensor%u first%u K%u original_sha%s prepared_sha%s input_sha%s prediction_sha%s;NO_LEARNED_BYTES_PRINTED\n",
   s,p.tensor,p.first,p.width,Cache::Hex(Cache::Hash(p.original.data(),p.original.size())).c_str(),Cache::Hex(Cache::Hash(p.prepared.data(),p.prepared.size())).c_str(),
   Cache::Hex(Cache::Hash(p.input.data(),p.input.size())).c_str(),Cache::Hex(Cache::Hash(p.expected.data(),128)).c_str());
 }
 Require(model.Stable() && model.Epoch()==epoch,"Original changed during export;DO NOT COMPILE partial outputs.");
 puts("PASS_PRIVATE_Q4_STREAM_EXPORT samples9 fullK5120/17408 outputs32 each,original-authenticated/unchanged;6144B recipe1,not installed caches;NO DEVICE/HARDWARE/MODEL_QUALITY/SPEED_PROOF");return 0;
}
}
int main(int argc,char** argv){try{return Run(argc,argv);}catch(const std::exception& e){fprintf(stderr,"Q4_STREAM_EXPORT_REFUSED:%s\n",e.what());return 1;}}
